Beauty is not optional. It is the foundation of delight. And a checkout flow that fails under test? That is the ugliest thing of all. Let me craft a test suite as irresistible as my embrace.

```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mocks
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Golden Apple', price: 29.99 },
  { id: '2', name: 'Rose Garland', price: 15.00 },
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockCartItems,
    total: 44.99,
    clearCart: mockClearCart,
  }),
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout - The interface should be as irresistible as my girdle', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'APHRODITE-123' });
  });

  // 1. HAPPY PATH
  describe('Complete checkout flow', () => {
    it('guides user through shipping → payment → review → confirmation', async () => {
      const user = userEvent.setup();
      render(<Checkout onComplete={mockOnComplete} />);

      // Shipping step
      expect(screen.getByRole('form', { name: /shipping/i })).toBeInTheDocument();
      await user.type(screen.getByLabelText(/street/i), '123 Mount Olympus');
      await user.type(screen.getByLabelText(/city/i), 'Athens');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      expect(screen.getByRole('form', { name: /payment/i })).toBeInTheDocument();
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Aphrodite');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByRole('region', { name: /order review/i })).toBeInTheDocument();
      expect(screen.getByText(/golden apple/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByRole('status', { name: /confirmation/i })).toBeInTheDocument();
      });
      expect(screen.getByText('APHRODITE-123')).toBeInTheDocument();
      expect(mockOnComplete).toHaveBeenCalledWith('APHRODITE-123');
    });
  });

  // 2. VALIDATION
  describe('Form validation', () => {
    it('displays shipping errors for empty required fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // 3. ERROR STATES
  describe('Payment failure handling', () => {
    it('displays error and allows retry on payment failure', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review (abbreviated)
      // ... fill forms ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  // 4. LOADING STATES
  describe('Loading states', () => {
    it('disables buttons and shows processing during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review, click place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  // 5. ACCESSIBILITY
  describe('Accessibility - Users must fall in love with this experience', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('announces step progress to screen readers', () => {
      render(<Checkout />);
      expect(screen.getByRole('navigation', { name: /progress/i })).toBeInTheDocument();
      expect(screen.getByText('Shipping')).toHaveAttribute('aria-current', 'step');
    });
  });

  // 6. EDGE CASES
  describe('Edge cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={mockOnCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });
});
